dleplugin.phpinstall:
$configFile = ENGINE_DIR . '/data/honeypot_config.json';
if (!file_exists($configFile)) {
    $defaultConfig = [
        'mode'              => 'hybrid',
        'tarpit_seconds'    => 15,
        'log_enabled'       => true,
        'log_max_lines'     => 2000,
        'vectors'           => [
            'wp_login'         => true,
            'wp_admin'         => true,
            'wp_xmlrpc'        => true,
            'wp_rest_users'    => true,
            'sensitive_files'  => true,
            'spider_trap'      => true,
            'webshell_catcher' => true,
            'dle_admin'        => false,
        ],
        'autoban_enabled'   => true,
        'autoban_threshold' => 3,
        'autoban_days'      => 0,
        'feed_enabled'      => true,
        'feed_token'        => 'hp_' . bin2hex(random_bytes(12)),
        'feed_format'       => 'plain',
        'abuseipdb_enabled' => false,
        'abuseipdb_key'     => '',
    ];
    @file_put_contents($configFile, json_encode($defaultConfig, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE), LOCK_EX);
}

// Ensure honeypot icon exists
$iconFile = ROOT_DIR . '/public/adminpanel/images/honeypot.png';
if (!file_exists($iconFile) && file_exists(ROOT_DIR . '/public/adminpanel/images/iptools.png')) {
    @copy(ROOT_DIR . '/public/adminpanel/images/iptools.png', $iconFile);
}

// Auto-create quarantine directory with strict security
$quarantineDir = ENGINE_DIR . '/data/quarantine';
if (!is_dir($quarantineDir)) {
    @mkdir($quarantineDir, 0750, true);
    $htaccess = "Order Deny,Allow\nDeny from all\nOptions -ExecCGI -Indexes\nRemoveHandler .php .phtml .php3 .php4 .php5 .php7 .phps .cgi .pl .py .asp .jsp .sh\n";
    @file_put_contents($quarantineDir . '/.htaccess', $htaccess, LOCK_EX);
    @file_put_contents($quarantineDir . '/index.html', '', LOCK_EX);
}

// Auto-create decoy endpoints in root if permissions allow
$wpAdminDir = ROOT_DIR . '/wp-admin';
if (!is_dir($wpAdminDir)) {
    @mkdir($wpAdminDir, 0755, true);
}

$decoyFiles = [
    ROOT_DIR . '/wp-login.php' => "<?php\n/* WordPress Login Decoy */\nrequire_once __DIR__ . '/engine/modules/honeypot.php';\nSiteHoneypot::handle('wp-login');\n",
    ROOT_DIR . '/wp-admin/index.php' => "<?php\n/* WordPress Admin Decoy Index */\nrequire_once __DIR__ . '/../engine/modules/honeypot.php';\nSiteHoneypot::handle('wp-admin');\n",
    ROOT_DIR . '/wp-admin/admin.php' => "<?php\n/* WordPress Admin Decoy Handler */\nrequire_once __DIR__ . '/../engine/modules/honeypot.php';\nSiteHoneypot::handle('wp-admin');\n",
    ROOT_DIR . '/xmlrpc.php' => "<?php\n/* WordPress XML-RPC Decoy */\nrequire_once __DIR__ . '/engine/modules/honeypot.php';\nSiteHoneypot::handle('xmlrpc');\n",
];

foreach ($decoyFiles as $path => $code) {
    if (!file_exists($path)) {
        @file_put_contents($path, $code, LOCK_EX);
    }
}

dleplugin.phpdelete:
$decoyFiles = [
    ROOT_DIR . '/wp-login.php',
    ROOT_DIR . '/wp-admin/index.php',
    ROOT_DIR . '/wp-admin/admin.php',
    ROOT_DIR . '/wp-admin/admin.gzip',
    ROOT_DIR . '/xmlrpc.php',
];
foreach ($decoyFiles as $file) {
    if (file_exists($file)) {
        $content = @file_get_contents($file);
        if ($content && (strpos($content, 'WordPress') !== false || strpos($file, 'admin.gzip') !== false)) {
            @unlink($file);
        }
    }
}
$wpAdminDir = ROOT_DIR . '/wp-admin';
if (is_dir($wpAdminDir)) {
    $files = @scandir($wpAdminDir);
    if ($files && count($files) <= 2) {
        @rmdir($wpAdminDir);
    }
}

// Clean up quarantine
$quarantineDir = ENGINE_DIR . '/data/quarantine';
if (is_dir($quarantineDir)) {
    $qFiles = @scandir($quarantineDir);
    if ($qFiles) {
        foreach ($qFiles as $qf) {
            if ($qf !== '.' && $qf !== '..') {
                @unlink($quarantineDir . '/' . $qf);
            }
        }
    }
    @rmdir($quarantineDir);
}

$configFile = ENGINE_DIR . '/data/honeypot_config.json';
if (file_exists($configFile)) {
    @unlink($configFile);
}
$logFile = ENGINE_DIR . '/data/honeypot.log';
if (file_exists($logFile)) {
    @unlink($logFile);
}

operation.replacecode:
// WordPress Honeypot & Threat Intelligence Virtual Route Interceptor
if (isset($_SERVER['REQUEST_URI'])) {
    $hpUri = $_SERVER['REQUEST_URI'];
    if (
        strpos($hpUri, '/wp-') !== false ||
        strpos($hpUri, '/xmlrpc') !== false ||
        strpos($hpUri, '/honeypot-feed') !== false ||
        strpos($hpUri, '/trap-spider') !== false ||
        strpos($hpUri, '/.env') !== false ||
        strpos($hpUri, '/.git') !== false ||
        strpos($hpUri, '.sql') !== false ||
        strpos($hpUri, '.bak') !== false
    ) {
        require_once DLEPlugins::Check(ENGINE_DIR . '/modules/honeypot.php');
        if (SiteHoneypot::handleRoute($hpUri)) {
            exit;
        }
    }
}

// WordPress Honeypot Spider Trap Injection
if (file_exists(ENGINE_DIR . '/modules/honeypot.php')) {
    require_once DLEPlugins::Check(ENGINE_DIR . '/modules/honeypot.php');
    $tpl->result['main'] = SiteHoneypot::injectSpiderTrap($tpl->result['main']);
}
